class ta_messaging(object):
    """
    Abstract Messaging library.

    This version of ta_messaging library supports following functionality:
        - LTE Messages handling  (based on tshark of wts)
        - https://gitlabe1.ext.net.nokia.com/abstract_library/ta_messaging/wikis/messaging-examples

    development project and code repository: https://gitlabe1.ext.net.nokia.com/abstract_library/ta_messaging

    developers mailing list: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2
    TIME_ALIAS_PREFIX = '__time_'

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self.binding_lib = importlib.import_module('ta_messaging.robot_binding')  # delayed import, only when robot runs
        configure_messaging_loggers()
        self.binding_lib.configure_flow_logic_logger()
        testenv.TestEnv()  # to register classes construction based on env
        MessageManager()  # to let it subscribe for msg_source creation during 'Library  ute_ue'

    def create_ue_alias(self, alias, ue_id, id_type):
        """
        Create abstract identification of UE (alias) from 'physical' identification

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of UE

        :param alias: abstract identification of UE that will be used later in script
        :param ue_id: physical/tool-specific identification of UE
        :param id_type: type of id (like 'wts')
        :return: None

        +------------------+-------+------------+-------------+
        |     Example                                         |
        +==================+=======+============+=============+
        | Create UE alias  | UE_1  | ue_id=101  | id_type=wts |
        +------------------+-------+------------+-------------+
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        get_alias_factory().create_ue_alias(alias=alias, ue_id=ue_id, id_type=id_type)

