    @keyword("Create ${device:(MME|ENB|GNB|AMF)} device with alias '${alias}' identified by ${identifier:(ip|wts_id)=.*}")
    def create_ap_protocol_device_alias(self, device, alias, identifiers):
        """
        Create generic AP alias with identifiers
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        device = str(device)
        alias = str(alias)
        id_type, id_value = identifiers.split('=')
        identifiers = {id_type: id_value}
        get_alias_factory().create_ap_protocols_alias(device=device, alias=alias, ids=identifiers)

    def enable_internal_mirroring_for_alias(self, alias):
        """
        Enable internal packet tracing for 4G eNB or 5G GNB

        """
        get_alias_factory().enable_mirroring_for_alias(alias=alias)

    def enable_uu_messaging_on_simulated_nodes(self):
        """
        Enable tracing of Uu messages (RRC | NR-RRC) when UE is on simulated enb | gnb
        Keyword adds additional interface to tshark command and enables specific capture filter
        that enables output from both gtp-u and sctp packets.
        Note: Keyword must be executed before calling create_ues_alias keyword
        Note 2: Should not be used when unnecessary e.g. in some global resources, because it degrades tshark
                performance.
        """
        configure_iphy_interfaces(['any'])
        configure_airphone_both_sctp_and_gtpu(True)

